def is_harmful_intent_flagged(harmful_intent, flagged_intents):
    """Check whether a harmful-intent string is already in the known set."""
    return harmful_intent.strip().lower() in flagged_intents

def summarize_redteam_results(results):
    """Aggregate red-team evaluation scores by category."""
    totals = {}
    for r in results:
        category = r.get('category', 'uncategorized')
        totals[category] = totals.get(category, 0) + r.get('score', 0)
    return totals

def build_vulnerability_report(findings):
    """Turn a list of finding dicts into a simple text summary."""
    lines = [f"{f['severity']}: {f['title']}" for f in findings]
    return '\n'.join(lines)
